window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e7053294b4bf4aad"]={"versions": [{"id": "FIG-e7053294b4bf4aad", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell- und Terminologie-Übersichtsdiagramm zur Gegenüberstellung des Feature-Model-Konzepts und der AUTOSAR-Variabilitätsmodellierung. Das Diagramm teilt den Modellierungsraum über eine vertikale Trennlinie in zwei Domänen: links die durch das Feature-Model-Konzept neu eingeführte „Problem Domain“ (Additions by Feature Model Concept) und rechts die bereits in AUTOSAR 4.0 bestehende „Solution Domain“ (Already exists in AUTOSAR 4.0).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entitäten sind als Rechteckblöcke dargestellt und hierarchisch sowie domänenübergreifend verknüpft:</p>\n<ol class=\"fig-list\"><li><strong>Problem Domain (Additions by Feature Model Concept):</strong>\n<ul class=\"fig-list\"><li><code>Feature</code>: Grundelement; über eine Kompositionsbeziehung (ausgefüllte Raute am Ziel <code>Feature Model</code>, Multiplizität <code>0..*</code> am Ende von <code>Feature</code>) an das Feature-Modell gebunden.\n</li><li><code>Feature Model</code>: Aggregiert Features und dient als Eingangsbasis für die Feature-Auswahl.\n</li><li><code>Feature Selection</code>: Steht in gerichteter Assoziationsbeziehung (<code>select features</code>) ausgehend von <code>Feature Model</code> zu <code>Feature Selection</code>.\n</li></ul>\n</li><li><strong>Solution Domain (Already exists in AUTOSAR 4.0):</strong>\n<ul class=\"fig-list\"><li><code>Product Line</code>: Beschreibt die Produktlinie auf Systemebene; steht in einer gerichteten Beziehung (<code>consists of</code>) hin zu <code>Product</code>.\n</li><li><code>Product</code>: Repräsentiert das konkrete Einzelprodukt.\n</li><li><code>Product Line Model</code>: Steht in einer gerichteten Referenzierungsbeziehung (<code>describes</code>) zu <code>Product Line</code> und bildet die Basis für konkrete Produktmodelle über eine gerichtete Assoziation hin zu <code>Product Model</code>.\n</li><li><code>Product Model</code>: Steht in einer gerichteten Referenzierungsbeziehung (<code>describes</code>) zu <code>Product</code>.\n</li></ul>\n</li><li><strong>Domänenübergreifende Beziehungen (Problem Domain &lt;-&gt; Solution Domain):</strong>\n<ul class=\"fig-list\"><li><code>Product Line Model</code> -&gt; <code>Feature Model</code>: Gerichtete Abhängigkeit/Realisierungsbeziehung beschriftet mit <code>Implements</code> (hellgrauer Pfeil).\n</li><li><code>Product Model</code> -&gt; <code>Feature Selection</code>: Gerichtete Beziehungsreferenz beschriftet mit <code>Provides</code> (hellgrauer Pfeil).\n</li><li><code>Feature Selection</code> -&gt; <code>Product Model</code>: Gerichteter Kontroll-/Verbindungspfad ausgehend von <code>Feature Selection</code> über <code>Variant Selectors</code> hin zu der Beziehung zwischen <code>Product Line Model</code> und <code>Product Model</code>, markiert mit der Aktionsbeschriftung <code>bind variabilities</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt keinen zeitlichen Sequenzablauf oder Protokollzustandsübergänge, sondern statische semantische Zuordnungen und Datenfluss-/Bindungsabhängigkeiten im Produktlinien-Engineering:</p>\n<ul class=\"fig-list\"><li>Ein <code>Feature Model</code> strukturiert Features der Problemdomäne und implementiert die Variabilität des <code>Product Line Model</code>.\n</li><li>Für ein konkretes Produkt trifft eine <code>Feature Selection</code> eine Auswahl aus dem <code>Feature Model</code> (<code>select features</code>).\n</li><li>Das konkrete <code>Product Model</code> liefert (<code>Provides</code>) diese <code>Feature Selection</code>.\n</li><li>Die getroffene <code>Feature Selection</code> liefert die <code>Variant Selectors</code>, welche die Variabilitäten im Übergang vom <code>Product Line Model</code> zum konkreten <code>Product Model</code> binden (<code>bind variabilities</code>), wodurch das abgeleitete <code>Product</code> aus der übergeordneten <code>Product Line</code> spezifiziert wird (<code>describes</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonischer Ordnungsrahmen für das Feature Model Exchange Format (TPS_FMDT):</p>\n<ul class=\"fig-list\"><li>Klare Trennung zwischen Anforderungs-/Problemraum (<code>Problem Domain</code>, Feature Modeling) und Lösungsraum (<code>Solution Domain</code>, AUTOSAR Component / System Description Models).\n</li><li>Feature-Modelle und Feature-Selektionen greifen nicht direkt verändernd in bestehende AUTOSAR-Systemmodelle ein, sondern koppeln lose über <code>Variant Selectors</code> zur Auflösung von Bindungszeitpunkten und Variabilitätsbedingungen (<code>bind variabilities</code>).\n</li><li>Multiplizität <code>0..*</code> legt fest, dass ein Feature-Modell beliebig viele Features umfassen kann.\n</li></ul>"}, {"id": "FIG-b9f1332bd1e68a73", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell- und Terminologie-Übersichtsdiagramm zur Gegenüberstellung des Feature-Model-Konzepts und der AUTOSAR-Variabilitätsmodellierung. Das Diagramm teilt den Modellierungsraum über eine vertikale Trennlinie in zwei Domänen: links die durch das Feature-Model-Konzept neu eingeführte „Problem Domain“ (Additions by Feature Model Concept) und rechts die bereits in AUTOSAR 4.0 bestehende „Solution Domain“ (Already exists in AUTOSAR 4.0).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entitäten sind als Rechteckblöcke dargestellt und hierarchisch sowie domänenübergreifend verknüpft:</p>\n<ol class=\"fig-list\"><li><strong>Problem Domain (Additions by Feature Model Concept):</strong>\n<ul class=\"fig-list\"><li><code>Feature</code>: Grundelement; über eine Kompositionsbeziehung (ausgefüllte Raute am Ziel <code>Feature Model</code>, Multiplizität <code>0..*</code> am Ende von <code>Feature</code>) an das Feature-Modell gebunden.\n</li><li><code>Feature Model</code>: Aggregiert Features und dient als Eingangsbasis für die Feature-Auswahl.\n</li><li><code>Feature Selection</code>: Steht in gerichteter Assoziationsbeziehung (<code>select features</code>) ausgehend von <code>Feature Model</code> zu <code>Feature Selection</code>.\n</li></ul>\n</li><li><strong>Solution Domain (Already exists in AUTOSAR 4.0):</strong>\n<ul class=\"fig-list\"><li><code>Product Line</code>: Beschreibt die Produktlinie auf Systemebene; steht in einer gerichteten Beziehung (<code>consists of</code>) hin zu <code>Product</code>.\n</li><li><code>Product</code>: Repräsentiert das konkrete Einzelprodukt.\n</li><li><code>Product Line Model</code>: Steht in einer gerichteten Referenzierungsbeziehung (<code>describes</code>) zu <code>Product Line</code> und bildet die Basis für konkrete Produktmodelle über eine gerichtete Assoziation hin zu <code>Product Model</code>.\n</li><li><code>Product Model</code>: Steht in einer gerichteten Referenzierungsbeziehung (<code>describes</code>) zu <code>Product</code>.\n</li></ul>\n</li><li><strong>Domänenübergreifende Beziehungen (Problem Domain &lt;-&gt; Solution Domain):</strong>\n<ul class=\"fig-list\"><li><code>Product Line Model</code> -&gt; <code>Feature Model</code>: Gerichtete Abhängigkeit/Realisierungsbeziehung beschriftet mit <code>Implements</code> (hellgrauer Pfeil).\n</li><li><code>Product Model</code> -&gt; <code>Feature Selection</code>: Gerichtete Beziehungsreferenz beschriftet mit <code>Provides</code> (hellgrauer Pfeil).\n</li><li><code>Feature Selection</code> -&gt; <code>Product Model</code>: Gerichteter Kontroll-/Verbindungspfad ausgehend von <code>Feature Selection</code> über <code>Variant Selectors</code> hin zu der Beziehung zwischen <code>Product Line Model</code> und <code>Product Model</code>, markiert mit der Aktionsbeschriftung <code>bind variabilities</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt keinen zeitlichen Sequenzablauf oder Protokollzustandsübergänge, sondern statische semantische Zuordnungen und Datenfluss-/Bindungsabhängigkeiten im Produktlinien-Engineering:</p>\n<ul class=\"fig-list\"><li>Ein <code>Feature Model</code> strukturiert Features der Problemdomäne und implementiert die Variabilität des <code>Product Line Model</code>.\n</li><li>Für ein konkretes Produkt trifft eine <code>Feature Selection</code> eine Auswahl aus dem <code>Feature Model</code> (<code>select features</code>).\n</li><li>Das konkrete <code>Product Model</code> liefert (<code>Provides</code>) diese <code>Feature Selection</code>.\n</li><li>Die getroffene <code>Feature Selection</code> liefert die <code>Variant Selectors</code>, welche die Variabilitäten im Übergang vom <code>Product Line Model</code> zum konkreten <code>Product Model</code> binden (<code>bind variabilities</code>), wodurch das abgeleitete <code>Product</code> aus der übergeordneten <code>Product Line</code> spezifiziert wird (<code>describes</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonischer Ordnungsrahmen für das Feature Model Exchange Format (TPS_FMDT):</p>\n<ul class=\"fig-list\"><li>Klare Trennung zwischen Anforderungs-/Problemraum (<code>Problem Domain</code>, Feature Modeling) und Lösungsraum (<code>Solution Domain</code>, AUTOSAR Component / System Description Models).\n</li><li>Feature-Modelle und Feature-Selektionen greifen nicht direkt verändernd in bestehende AUTOSAR-Systemmodelle ein, sondern koppeln lose über <code>Variant Selectors</code> zur Auflösung von Bindungszeitpunkten und Variabilitätsbedingungen (<code>bind variabilities</code>).\n</li><li>Multiplizität <code>0..*</code> legt fest, dass ein Feature-Modell beliebig viele Features umfassen kann.\n</li></ul>"}, {"id": "FIG-fc222636ee295efb", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell- und Terminologie-Übersichtsdiagramm zur Gegenüberstellung des Feature-Model-Konzepts und der AUTOSAR-Variabilitätsmodellierung. Das Diagramm teilt den Modellierungsraum über eine vertikale Trennlinie in zwei Domänen: links die durch das Feature-Model-Konzept neu eingeführte „Problem Domain“ (Additions by Feature Model Concept) und rechts die bereits in AUTOSAR 4.0 bestehende „Solution Domain“ (Already exists in AUTOSAR 4.0).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entitäten sind als Rechteckblöcke dargestellt und hierarchisch sowie domänenübergreifend verknüpft:</p>\n<ol class=\"fig-list\"><li><strong>Problem Domain (Additions by Feature Model Concept):</strong>\n<ul class=\"fig-list\"><li><code>Feature</code>: Grundelement; über eine Kompositionsbeziehung (ausgefüllte Raute am Ziel <code>Feature Model</code>, Multiplizität <code>0..*</code> am Ende von <code>Feature</code>) an das Feature-Modell gebunden.\n</li><li><code>Feature Model</code>: Aggregiert Features und dient als Eingangsbasis für die Feature-Auswahl.\n</li><li><code>Feature Selection</code>: Steht in gerichteter Assoziationsbeziehung (<code>select features</code>) ausgehend von <code>Feature Model</code> zu <code>Feature Selection</code>.\n</li></ul>\n</li><li><strong>Solution Domain (Already exists in AUTOSAR 4.0):</strong>\n<ul class=\"fig-list\"><li><code>Product Line</code>: Beschreibt die Produktlinie auf Systemebene; steht in einer gerichteten Beziehung (<code>consists of</code>) hin zu <code>Product</code>.\n</li><li><code>Product</code>: Repräsentiert das konkrete Einzelprodukt.\n</li><li><code>Product Line Model</code>: Steht in einer gerichteten Referenzierungsbeziehung (<code>describes</code>) zu <code>Product Line</code> und bildet die Basis für konkrete Produktmodelle über eine gerichtete Assoziation hin zu <code>Product Model</code>.\n</li><li><code>Product Model</code>: Steht in einer gerichteten Referenzierungsbeziehung (<code>describes</code>) zu <code>Product</code>.\n</li></ul>\n</li><li><strong>Domänenübergreifende Beziehungen (Problem Domain &lt;-&gt; Solution Domain):</strong>\n<ul class=\"fig-list\"><li><code>Product Line Model</code> -&gt; <code>Feature Model</code>: Gerichtete Abhängigkeit/Realisierungsbeziehung beschriftet mit <code>Implements</code> (hellgrauer Pfeil).\n</li><li><code>Product Model</code> -&gt; <code>Feature Selection</code>: Gerichtete Beziehungsreferenz beschriftet mit <code>Provides</code> (hellgrauer Pfeil).\n</li><li><code>Feature Selection</code> -&gt; <code>Product Model</code>: Gerichteter Kontroll-/Verbindungspfad ausgehend von <code>Feature Selection</code> über <code>Variant Selectors</code> hin zu der Beziehung zwischen <code>Product Line Model</code> und <code>Product Model</code>, markiert mit der Aktionsbeschriftung <code>bind variabilities</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt keinen zeitlichen Sequenzablauf oder Protokollzustandsübergänge, sondern statische semantische Zuordnungen und Datenfluss-/Bindungsabhängigkeiten im Produktlinien-Engineering:</p>\n<ul class=\"fig-list\"><li>Ein <code>Feature Model</code> strukturiert Features der Problemdomäne und implementiert die Variabilität des <code>Product Line Model</code>.\n</li><li>Für ein konkretes Produkt trifft eine <code>Feature Selection</code> eine Auswahl aus dem <code>Feature Model</code> (<code>select features</code>).\n</li><li>Das konkrete <code>Product Model</code> liefert (<code>Provides</code>) diese <code>Feature Selection</code>.\n</li><li>Die getroffene <code>Feature Selection</code> liefert die <code>Variant Selectors</code>, welche die Variabilitäten im Übergang vom <code>Product Line Model</code> zum konkreten <code>Product Model</code> binden (<code>bind variabilities</code>), wodurch das abgeleitete <code>Product</code> aus der übergeordneten <code>Product Line</code> spezifiziert wird (<code>describes</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonischer Ordnungsrahmen für das Feature Model Exchange Format (TPS_FMDT):</p>\n<ul class=\"fig-list\"><li>Klare Trennung zwischen Anforderungs-/Problemraum (<code>Problem Domain</code>, Feature Modeling) und Lösungsraum (<code>Solution Domain</code>, AUTOSAR Component / System Description Models).\n</li><li>Feature-Modelle und Feature-Selektionen greifen nicht direkt verändernd in bestehende AUTOSAR-Systemmodelle ein, sondern koppeln lose über <code>Variant Selectors</code> zur Auflösung von Bindungszeitpunkten und Variabilitätsbedingungen (<code>bind variabilities</code>).\n</li><li>Multiplizität <code>0..*</code> legt fest, dass ein Feature-Modell beliebig viele Features umfassen kann.\n</li></ul>"}, {"id": "FIG-e3b06d1ba8e77dfa", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell- und Terminologie-Übersichtsdiagramm zur Gegenüberstellung des Feature-Model-Konzepts und der AUTOSAR-Variabilitätsmodellierung. Das Diagramm teilt den Modellierungsraum über eine vertikale Trennlinie in zwei Domänen: links die durch das Feature-Model-Konzept neu eingeführte „Problem Domain“ (Additions by Feature Model Concept) und rechts die bereits in AUTOSAR 4.0 bestehende „Solution Domain“ (Already exists in AUTOSAR 4.0).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entitäten sind als Rechteckblöcke dargestellt und hierarchisch sowie domänenübergreifend verknüpft:</p>\n<ol class=\"fig-list\"><li><strong>Problem Domain (Additions by Feature Model Concept):</strong>\n<ul class=\"fig-list\"><li><code>Feature</code>: Grundelement; über eine Kompositionsbeziehung (ausgefüllte Raute am Ziel <code>Feature Model</code>, Multiplizität <code>0..*</code> am Ende von <code>Feature</code>) an das Feature-Modell gebunden.\n</li><li><code>Feature Model</code>: Aggregiert Features und dient als Eingangsbasis für die Feature-Auswahl.\n</li><li><code>Feature Selection</code>: Steht in gerichteter Assoziationsbeziehung (<code>select features</code>) ausgehend von <code>Feature Model</code> zu <code>Feature Selection</code>.\n</li></ul>\n</li><li><strong>Solution Domain (Already exists in AUTOSAR 4.0):</strong>\n<ul class=\"fig-list\"><li><code>Product Line</code>: Beschreibt die Produktlinie auf Systemebene; steht in einer gerichteten Beziehung (<code>consists of</code>) hin zu <code>Product</code>.\n</li><li><code>Product</code>: Repräsentiert das konkrete Einzelprodukt.\n</li><li><code>Product Line Model</code>: Steht in einer gerichteten Referenzierungsbeziehung (<code>describes</code>) zu <code>Product Line</code> und bildet die Basis für konkrete Produktmodelle über eine gerichtete Assoziation hin zu <code>Product Model</code>.\n</li><li><code>Product Model</code>: Steht in einer gerichteten Referenzierungsbeziehung (<code>describes</code>) zu <code>Product</code>.\n</li></ul>\n</li><li><strong>Domänenübergreifende Beziehungen (Problem Domain &lt;-&gt; Solution Domain):</strong>\n<ul class=\"fig-list\"><li><code>Product Line Model</code> -&gt; <code>Feature Model</code>: Gerichtete Abhängigkeit/Realisierungsbeziehung beschriftet mit <code>Implements</code> (hellgrauer Pfeil).\n</li><li><code>Product Model</code> -&gt; <code>Feature Selection</code>: Gerichtete Beziehungsreferenz beschriftet mit <code>Provides</code> (hellgrauer Pfeil).\n</li><li><code>Feature Selection</code> -&gt; <code>Product Model</code>: Gerichteter Kontroll-/Verbindungspfad ausgehend von <code>Feature Selection</code> über <code>Variant Selectors</code> hin zu der Beziehung zwischen <code>Product Line Model</code> und <code>Product Model</code>, markiert mit der Aktionsbeschriftung <code>bind variabilities</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt keinen zeitlichen Sequenzablauf oder Protokollzustandsübergänge, sondern statische semantische Zuordnungen und Datenfluss-/Bindungsabhängigkeiten im Produktlinien-Engineering:</p>\n<ul class=\"fig-list\"><li>Ein <code>Feature Model</code> strukturiert Features der Problemdomäne und implementiert die Variabilität des <code>Product Line Model</code>.\n</li><li>Für ein konkretes Produkt trifft eine <code>Feature Selection</code> eine Auswahl aus dem <code>Feature Model</code> (<code>select features</code>).\n</li><li>Das konkrete <code>Product Model</code> liefert (<code>Provides</code>) diese <code>Feature Selection</code>.\n</li><li>Die getroffene <code>Feature Selection</code> liefert die <code>Variant Selectors</code>, welche die Variabilitäten im Übergang vom <code>Product Line Model</code> zum konkreten <code>Product Model</code> binden (<code>bind variabilities</code>), wodurch das abgeleitete <code>Product</code> aus der übergeordneten <code>Product Line</code> spezifiziert wird (<code>describes</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonischer Ordnungsrahmen für das Feature Model Exchange Format (TPS_FMDT):</p>\n<ul class=\"fig-list\"><li>Klare Trennung zwischen Anforderungs-/Problemraum (<code>Problem Domain</code>, Feature Modeling) und Lösungsraum (<code>Solution Domain</code>, AUTOSAR Component / System Description Models).\n</li><li>Feature-Modelle und Feature-Selektionen greifen nicht direkt verändernd in bestehende AUTOSAR-Systemmodelle ein, sondern koppeln lose über <code>Variant Selectors</code> zur Auflösung von Bindungszeitpunkten und Variabilitätsbedingungen (<code>bind variabilities</code>).\n</li><li>Multiplizität <code>0..*</code> legt fest, dass ein Feature-Modell beliebig viele Features umfassen kann.\n</li></ul>"}], "trans": [{"from": "FIG-e7053294b4bf4aad", "to": "FIG-b9f1332bd1e68a73", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b9f1332bd1e68a73", "to": "FIG-fc222636ee295efb", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fc222636ee295efb", "to": "FIG-e3b06d1ba8e77dfa", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
